sys_script_client.script:
function onLoad() {
    var outcome = g_form.getValue('outcome');
    var currentDecision = g_form.getValue('decision');
    var validOptions = ['approve'];
    var isAmendTrade = (outcome == 'Amend Trade');

    g_form.clearOptions('decision');
    g_form.addOption('decision', '', '-- None --', 0);
    g_form.addOption('decision', 'approve', 'Approve');

    //Cancellation of trade in GHSS as part of MSSCUSTODY-6987 and PP Test

    if (!isAmendTrade) {
        g_form.removeOption('decision', 'Reject and create a new task', 'Reject and create a new maker task');
        g_form.addOption('decision', 'Reject and create a new task', 'Reject and create a new task');
        g_form.removeOption('decision', 'reject_ghss', 'Cancellation of trade in GHSS');
        g_form.removeOption('decision', 'reject_amend', 'Reject in GHSS');
        validOptions.push('Reject and create a new task');
    }
    if (isAmendTrade && !g_scratchpad.multipleChecker) {
        if (g_scratchpad.trdLifeCycle == 'PAPP' && g_scratchpad.trdSubStatus == 'R&D Capture') {
            g_form.addOption('decision', 'reject_ghss', 'Cancellation of trade in GHSS');
            g_form.removeOption('decision', 'Reject and create a new task', 'Reject and create a new task');
			g_form.removeOption('decision', 'reject_amend', 'Reject in GHSS');
            g_form.addOption('decision', 'Reject and create a new task', 'Reject and create a new maker task');
        } else {
            g_form.addOption('decision', 'reject_amend', 'Reject in GHSS');
            validOptions.push('reject_amend');
        }
    }

    // g_form.addInfoMessage(' Val 1 ' + g_scratchpad.multipleChecker + 'val 2' + isAmendTrade);
    if (g_scratchpad.multipleChecker) {
        if (isAmendTrade) {
            if (g_scratchpad.trdLifeCycle == 'PAPP' && g_scratchpad.trdSubStatus == 'R&D Capture') {
                g_form.addOption('decision', 'manually_close', 'Review and close the task');
                g_form.addOption('decision', 'reject_ghss', 'Cancellation of trade in GHSS');
                g_form.addOption('decision', 'Reject and create a new task', 'Reject and create a new maker task');
				g_form.removeOption('decision', 'reject_amend', 'Reject in GHSS');
                validOptions.push('reject_ghss');
                validOptions.push('manually_close');
                validOptions.push('Reject and create a new task');
            } else {
                g_form.addOption('decision', 'manually_close', 'Review and close the task');
                g_form.addOption('decision', 'reject_amend', 'Reject in GHSS');
                g_form.removeOption('decision', 'Reject and create a new task', 'Reject and create a new task');
                validOptions.push('manually_close');
                validOptions.push('reject_amend');
            }
        } else {
            g_form.removeOption('decision', 'Reject and create a new task', 'Reject and create a new maker task');
            g_form.addOption('decision', 'Reject and create a new task', 'Reject and create a new task');
            g_form.addOption('decision', 'manually_close', 'Review and close the task');
            g_form.removeOption('decision', 'reject_ghss', 'Cancellation of trade in GHSS');
			g_form.removeOption('decision', 'reject_amend', 'Reject in GHSS');
            validOptions.push('Reject and create a new task');
            validOptions.push('manually_close');
        }
    }

    if (validOptions.indexOf(currentDecision) > -1) {
        g_form.setValue('decision', currentDecision);
    } else {
        g_form.setValue('decision', '');
    }
}
